/** An integer column as a number (drivers return int8 as a string, a bigint or a number). */
export function sqlInteger(value: unknown): unknown {
  if (typeof value === "bigint") return Number(value);
  if (typeof value === "string" && /^-?\d+$/.test(value)) return Number(value);
  return value;
}

/** A jsonb column as parsed JSON (some drivers return the text). */
export function sqlJson(value: unknown): unknown {
  return typeof value === "string" ? (JSON.parse(value) as unknown) : value;
}

/** `decode(value)`, or null for SQL NULL. */
export function nullable<T>(value: unknown, decode: (value: unknown) => T): T | null {
  return value === null || value === undefined ? null : decode(value);
}

/** A JSON array (jsonb column or nested field) with `decode` applied to each element. */
export function jsonList<T>(value: unknown, decode: (item: unknown) => T): T[] {
  const list = sqlJson(value);
  if (!Array.isArray(list)) throw new ConstraintViolation({}, "Expected a JSON array");
  return list.map((item: unknown) => decode(item));
}

/** Field `name` of a JSON object (undefined if `value` is not an object). */
export function jsonField(value: unknown, name: string): unknown {
  if (typeof value !== "object" || value === null) return undefined;
  return (value as Readonly<Record<string, unknown>>)[name];
}

/** A parameter value as SQL sends it: decimals as text, absent as NULL. */
export function sqlParam(value: unknown): unknown {
  if (value === undefined) return null;
  return Decimal.isDecimal(value) ? value.toString() : value;
}

